{"code": "import urllib.request, io, sys

urls = {
  "aci_impact": "https://www.aci-europe.org/downloads/resources/The%20Impact%20of%20An%20Airport.pdf",
  "aci_synopsis": "https://www.aci-europe.org/downloads/content/ACI%20EUROPE%20SYNOPSIS%20-%20BENEFITS%20OF%20AIRPORTS%20%20AIR%20CONNECTIVITY%20digital.pdf",
  "seo_study": "https://www.seo.nl/wp-content/uploads/2024/10/2024-125A-The-Economic-and-social-impact-of-European-Airports-and-air-connectivity.pdf",
}

for name, url in urls.items():
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        data = urllib.request.urlopen(req, timeout=30).read()
        print(name, "bytes:", len(data))
        open(f"/tmp/{name}.pdf", "wb").write(data)
    except Exception as e:
        print(name, "ERROR:", e)
"}

{"code": "import subprocess, sys
# Try to extract text with pdftotext if available
for f in ["aci_impact", "aci_synopsis", "seo_study"]:
    try:
        r = subprocess.run(["pdftotext", f"/tmp/{f}.pdf", f"/tmp/{f}.txt"], capture_output=True, text=True, timeout=60)
        print(f, "rc:", r.returncode, r.stderr[:200])
    except FileNotFoundError:
        print("pdftotext not found")
        break
    except Exception as e:
        print(f, "err", e)
"}

