{"code": "from pypdf import PdfReader

for name in ["aci_impact", "aci_synopsis", "seo_study"]:
    try:
        r = PdfReader(f"/tmp/{name}.pdf")
        print("="*80)
        print(name, "pages:", len(r.pages))
        text = "\n".join((p.extract_text() or "") for p in r.pages)
        open(f"/tmp/{name}.txt","w").write(text)
        print("chars:", len(text))
    except Exception as e:
        print(name, "ERROR", e)
"}

{"code": "import re
text = open("/tmp/aci_impact.txt").read()
# find the jobs-per-passenger section
for kw in ["1000 extra passengers", "1 million passengers", "direct jobs", "less than 1 million"]:
    for m in re.finditer(re.escape(kw), text):
        s = max(0, m.start()-400); e = min(len(text), m.end()+400)
        print("="*70)
        print(text[s:e].replace("\n"," "))
        print()
"}

